function setWikiLink(element,text,page){if(!element)return;element.textContent="";const link=document.createElement("a");link.className="wiki-link";link.href=wiki(page||text);link.target="_blank";link.rel="noopener noreferrer";link.textContent=text;element.append(link)}
function requestRender(){requestAnimationFrame(()=>{render();dom.title.textContent=eraFor(Number(dom.year.value)).title})}
function debugValues(){return{scaleX:Number(dom.flagDebugScaleX.value),scaleY:Number(dom.flagDebugScaleY.value),offsetX:Number(dom.flagDebugOffsetX.value),offsetY:Number(dom.flagDebugOffsetY.value),rotation:Number(dom.flagDebugRotation.value),color:dom.flagDebugColor.value,flagFill:dom.flagDebugFill.value}}
function updateFlagDebugUi(){const values=debugValues();document.querySelector("#flagDebugScaleXValue").textContent=`${values.scaleX.toFixed(2)}×`;document.querySelector("#flagDebugScaleYValue").textContent=`${values.scaleY.toFixed(2)}×`;document.querySelector("#flagDebugOffsetXValue").textContent=values.offsetX;document.querySelector("#flagDebugOffsetYValue").textContent=values.offsetY;document.querySelector("#flagDebugRotationValue").textContent=`${values.rotation}°`;document.querySelector("#flagDebugColorValue").textContent=values.color.toUpperCase();document.querySelector("#flagDebugFillValue").textContent=values.flagFill.toUpperCase()}
function loadFlagDebug(){if(!selected)return;const year=Number(dom.year.value),values=flagDebugSettings(selected,year);dom.flagDebugScaleX.value=values.scaleX;dom.flagDebugScaleY.value=values.scaleY;dom.flagDebugOffsetX.value=values.offsetX;dom.flagDebugOffsetY.value=values.offsetY;dom.flagDebugRotation.value=values.rotation;dom.flagDebugColor.value=values.color;dom.flagDebugFill.value=values.flagFill;dom.flagDebugCurrent.textContent=`当前实体：${displayNameAt(selected,year)} · ${year}`;dom.flagDebugPreview.src=flagAssetFor(selected,year).path;updateFlagDebugUi()}
function initFlagDebug(){dom.flagDebugButton.addEventListener("click",()=>{loadFlagDebug();dom.flagDebugDialog.showModal()});dom.flagDebugClose.addEventListener("click",()=>dom.flagDebugDialog.close());[dom.flagDebugScaleX,dom.flagDebugScaleY,dom.flagDebugOffsetX,dom.flagDebugOffsetY,dom.flagDebugRotation,dom.flagDebugColor,dom.flagDebugFill].forEach(input=>input.addEventListener("input",updateFlagDebugUi));dom.flagDebugSave.addEventListener("click",()=>{if(!selected)return;const data=readFlagDebug();data[flagDebugKey(selected,Number(dom.year.value))]=debugValues();localStorage.setItem(EURO_FLAG_DEBUG_STORAGE,JSON.stringify(data,null,2));dom.flagDebugStatus.textContent="已保存到浏览器。";applyFlagDebugSettings(selected,Number(dom.year.value));historicalStyles(Number(dom.year.value))});dom.flagDebugReset.addEventListener("click",()=>{if(!selected)return;const data=readFlagDebug();delete data[flagDebugKey(selected,Number(dom.year.value))];localStorage.setItem(EURO_FLAG_DEBUG_STORAGE,JSON.stringify(data,null,2));loadFlagDebug();dom.flagDebugStatus.textContent="已恢复默认值。"});dom.flagDebugExport.addEventListener("click",()=>{const blob=new Blob([JSON.stringify(readFlagDebug(),null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),anchor=document.createElement("a");anchor.href=url;anchor.download="euro-flag-debug.json";anchor.click();URL.revokeObjectURL(url)})}
function init(){dom.schematicCountries.forEach(bindCountry);dom.year.addEventListener("input",()=>{stop();updateBoundaryDebugTargets();requestRender()});dom.play.addEventListener("click",toggle);dom.overview.addEventListener("click",overview);dom.brand.addEventListener("click",overview);dom.about.addEventListener("click",()=>dom.dialog.showModal());dom.close.addEventListener("click",()=>dom.dialog.close());dom.confirm.addEventListener("click",()=>dom.dialog.close());dom.jump.addEventListener("click",()=>{const raw=prompt("输入1816—2026之间的年份：",dom.year.value);if(raw===null)return;dom.year.value=Math.max(1816,Math.min(2026,parseInt(raw,10)||Number(dom.year.value)));stop();requestRender()});initFlagDebug();initBoundaryDebug();requestRender()}
init();
